@import url('https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Figma DNA — white canvas, five-color primary system, crisp 8px grid */
.theme-figma-dna {
  --bg: oklch(1 0 0);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.965 0 0);
  --fg: oklch(0.18 0 0);
  --fg-muted: oklch(0.55 0 0);
  --accent: oklch(0.662 0.183 249.2);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.591 0.244 291.7);
  --line: oklch(0.9 0 0);
  --success: oklch(0.742 0.182 153.0);
  --warning: oklch(0.714 0.186 41.3);
  --danger: oklch(0.652 0.234 26.7);

  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;

  --shadow-1: 0 0 0 1px oklch(0 0 0 / 8%);
  --shadow-2: 0 2px 8px oklch(0 0 0 / 12%), 0 0 0 1px oklch(0 0 0 / 6%);
  --shadow-3: 0 12px 32px -8px oklch(0 0 0 / 22%);
  --glow: 0 0 0 2px var(--accent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Instrument Sans", "Inter", sans-serif;
  --font-body: "Instrument Sans", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.025em;
  --label-transform: none;
  --label-tracking: 0.005em;

  background-color: var(--bg);
  background-image:
    linear-gradient(oklch(0 0 0 / 3.5%) 1px, transparent 1px),
    linear-gradient(90deg, oklch(0 0 0 / 3.5%) 1px, transparent 1px);
  background-size: 8px 8px;
  color: var(--fg);
  font-family: var(--font-body);
  font-size: 0.875rem;
}

.theme-figma-dna h1,
.theme-figma-dna h2,
.theme-figma-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 700;
}

/* Five-color primary system rotated across repeated blocks */
.theme-figma-dna li:nth-child(5n + 1) svg {
  color: oklch(0.62 0.22 25);
}
.theme-figma-dna li:nth-child(5n + 2) svg {
  color: oklch(0.72 0.17 55);
}
.theme-figma-dna li:nth-child(5n + 3) svg {
  color: oklch(0.55 0.2 295);
}
.theme-figma-dna li:nth-child(5n + 4) svg {
  color: oklch(0.65 0.17 150);
}
.theme-figma-dna li:nth-child(5n + 5) svg {
  color: oklch(0.6 0.19 250);
}

/* signature */
.theme-figma-dna { --font-ui: var(--font-display); }
.theme-figma-dna h1::after { content: ""; display: block; height: 4px; width: 5rem; margin-top: 0.6rem; background: linear-gradient(90deg, #ff3737 0 20%, #ff7237 0 40%, #874fff 0 60%, #24cb71 0 80%, #0d99ff 0 100%); }

/* depth */
.theme-figma-dna thead th { font-size: 0.6875rem; font-weight: 600; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-figma-dna td { border-bottom: 1px solid color-mix(in oklab, var(--line) 55%, transparent); font-size: 0.8125rem; }
.theme-figma-dna tbody tr:hover { background: oklch(0.97 0.013 240); box-shadow: inset 0 0 0 1px oklch(0.67 0.18 249 / 50%); }
.theme-figma-dna a { color: var(--accent); text-decoration: none; }
.theme-figma-dna a:hover { text-decoration: underline; }
.theme-figma-dna input, .theme-figma-dna select, .theme-figma-dna textarea { background: var(--surface-2); border: 1px solid transparent; transition: border-color 80ms ease; }
.theme-figma-dna input:hover, .theme-figma-dna select:hover, .theme-figma-dna textarea:hover { border-color: var(--line); }
.theme-figma-dna input:focus-visible, .theme-figma-dna select:focus-visible, .theme-figma-dna textarea:focus-visible { outline: none; background: var(--bg); border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.theme-figma-dna button:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.theme-figma-dna kbd { background: var(--surface-2); border: 1px solid var(--line); border-radius: var(--radius-sm); font-size: 0.75em; padding: 0.1em 0.4em; }
.theme-figma-dna ::selection { background: oklch(0.67 0.18 249 / 25%); }
.theme-figma-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-figma-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-figma-dna ::-webkit-scrollbar-thumb { background: oklch(0.78 0 0); border-radius: var(--radius-pill); border: 2px solid var(--bg); }
.theme-figma-dna .themed-border { border-style: dashed; border-color: var(--accent); }
.theme-figma-dna .label-caps { font-size: 0.6875rem; color: var(--fg-muted); }
.theme-figma-dna button:active { transform: translateY(1px); }

/* alt mode: auto-derived dark variant */
.theme-figma-dna.alt-mode {
  --bg: oklch(0.145 0.000 0.0);
  --surface: oklch(0.185 0.000 0.0);
  --surface-2: oklch(0.225 0.000 0.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image:
    linear-gradient(oklch(1 0 0 / 4.5%) 1px, transparent 1px),
    linear-gradient(90deg, oklch(1 0 0 / 4.5%) 1px, transparent 1px);
  background-size: 8px 8px;
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
